// Prepare WA message tailored to buyer locale
const data = $input.item.json.data;
const locale = data.locale || 'id';
let text = '';

if (locale === 'id' || locale === 'ms') {
  text = `Halo ${data.buyerName}! Pembayaran pesanan *${data.orderCode}* telah kami terima.\n\n*Produk:* ${data.productTitle}\n*Akses Produk:* ${data.digitalFileUrl || 'https://etalase.online/' + data.storeSlug}\n\nTerima kasih telah berbelanja di ${data.storeSlug}.etalase.online!`;
} else {
  text = `Hello ${data.buyerName}! We have received payment for order *${data.orderCode}*.\n\n*Item:* ${data.productTitle}\n*Access Link:* ${data.digitalFileUrl || 'https://etalase.online/' + data.storeSlug}\n\nThank you for shopping at ${data.storeSlug}.etalase.online!`;
}

return [{ json: { target: data.buyerWhatsapp, message: text, orderCode: data.orderCode } }];
